var suite=new Suite("Premium",2,150m);var hospedes=new[]{new Hospede("Ana"),new Hospede("João")};var reserva=new Reserva(suite,hospedes,12);Console.WriteLine($"Total: {reserva.Total():C}"); record Hospede(string Nome);record Suite(string Tipo,int Capacidade,decimal Diaria);class Reserva {private readonly Suite suite;private readonly Hospede[] hospedes;private readonly int dias;public Reserva(Suite suite,Hospede[] hospedes,int dias){if(dias<=0||hospedes.Length==0||hospedes.Length>suite.Capacidade)throw new ArgumentException("Reserva inválida");this.suite=suite;this.hospedes=hospedes;this.dias=dias;}public decimal Total()=>suite.Diaria*dias*(dias>=10?0.9m:1m);}
